import { sql } from 'drizzle-orm';
import { bigint, boolean, index, integer, jsonb, pgTable, primaryKey, text, timestamp, uniqueIndex, uuid } from 'drizzle-orm/pg-core';

/*
 * Conventions (see Notion → Data model):
 * - IDs are UUID v7 (generated by the app or by devices)
 * - Money columns are bigint millimes
 * - Every business table carries tenant_id and/or branch_id
 * - snake_case columns, plural table names
 */

const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp('updated_at', { withTimezone: true }).notNull().defaultNow();
const money = (name: string) => bigint(name, { mode: 'number' });

// ── Organization ────────────────────────────────────────────────

/** A business using the SaaS (one owner account, one or many branches). */
export const tenants = pgTable('tenants', {
  id: uuid('id').primaryKey(),
  name: text('name').notNull(),
  /** Matricule fiscal, printed on receipts and factures. */
  taxId: text('tax_id'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/** One physical location: a café, a restaurant, a shop. */
export const branches = pgTable('branches', {
  id: uuid('id').primaryKey(),
  tenantId: uuid('tenant_id')
    .notNull()
    .references(() => tenants.id),
  name: text('name').notNull(),
  type: text('type', { enum: ['cafe', 'restaurant', 'retail'] }).notNull().default('cafe'),
  address: text('address'),
  /** Printed on receipts. */
  phone: text('phone'),
  /** Last line of the receipt: "Merci de votre visite !". */
  receiptFooter: text('receipt_footer'),
  /** Shown in the customer app (owner opts in), with its city for the search. */
  listed: boolean('listed').notNull().default(false),
  city: text('city'),
  /**
   * Shared secret of the café's local network: POS devices sign their requests to the
   * Hub with it (HMAC), so a customer on the café Wi-Fi can't send orders. Created on first use.
   */
  lanKey: text('lan_key'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

// ── Owner accounts ──────────────────────────────────────────────

export const ownerRoles = ['owner', 'manager'] as const;
export type OwnerRole = (typeof ownerRoles)[number];

/** People who log in to the owner app (email + password). */
export const ownerUsers = pgTable(
  'owner_users',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    /** Always stored lowercase. */
    email: text('email').notNull().unique(),
    /** argon2id hash — never the password itself. */
    passwordHash: text('password_hash').notNull(),
    name: text('name').notNull(),
    role: text('role', { enum: ownerRoles }).notNull().default('owner'),
    /** Gets yesterday's summary by email each morning (can turn it off). */
    dailyEmail: boolean('daily_email').notNull().default(true),
    /** Last day (YYYY-MM-DD, Tunis) the summary was sent for — so it goes out once. */
    dailyEmailSentFor: text('daily_email_sent_for'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('owner_users_tenant_idx').on(t.tenantId)],
);

/**
 * Long-lived login sessions. Each refresh gives a NEW token and revokes the old one
 * (rotation). Using a revoked token again = stolen → all sessions of the user are revoked.
 */
export const refreshTokens = pgTable(
  'refresh_tokens',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => ownerUsers.id),
    /** sha256 of the token. */
    tokenHash: text('token_hash').notNull().unique(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('refresh_tokens_user_idx').on(t.userId)],
);

// ── Devices ─────────────────────────────────────────────────────

export const deviceRoles = ['hub', 'pos', 'kds'] as const;
export type DeviceRole = (typeof deviceRoles)[number];

/** A paired POS / Hub / KDS. `code` (T1, T2…) prefixes its receipt numbers. */
export const devices = pgTable(
  'devices',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    code: text('code').notNull(),
    name: text('name').notNull(),
    role: text('role', { enum: deviceRoles }).notNull(),
    /** Ed25519 public key (base64url) — verifies receipts signed by this device. */
    publicKey: text('public_key').notNull(),
    /** sha256 of the device token. The token itself is never stored. */
    tokenHash: text('token_hash').notNull().unique(),
    disabled: boolean('disabled').notNull().default(false),
    /** Highest deviceSeq received — used to detect missing events. */
    lastSeq: bigint('last_seq', { mode: 'number' }).notNull().default(0),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }),
    /** Secondary POS may take payments only if the owner allows it (the Hub always can). */
    canTakePayments: boolean('can_take_payments').notNull().default(false),
    /** Hub only: its addresses on the café network (["192.168.1.20"]) + port, reported by the Hub. */
    lanAddresses: jsonb('lan_addresses').$type<string[]>().notNull().default(sql`'[]'::jsonb`),
    lanPort: integer('lan_port'),
    createdAt: createdAt(),
  },
  (t) => [index('devices_branch_idx').on(t.branchId)],
);

/** One-time code shown in the owner app (QR) to pair a new device. */
export const pairingCodes = pgTable('pairing_codes', {
  code: text('code').primaryKey(),
  branchId: uuid('branch_id')
    .notNull()
    .references(() => branches.id),
  role: text('role', { enum: deviceRoles }).notNull(),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  usedAt: timestamp('used_at', { withTimezone: true }),
  createdAt: createdAt(),
});

// ── Catalog (owned by the cloud, pulled by devices) ─────────────

export const categories = pgTable(
  'categories',
  {
    id: uuid('id').primaryKey(),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    name: text('name').notNull(),
    sortOrder: integer('sort_order').notNull().default(0),
    color: text('color'),
    /** Must be set to now() on EVERY change — the POS pulls "changed since cursor". */
    updatedAt: updatedAt(),
    /** Soft delete: the row stays so the POS learns about the deletion on its next pull. */
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
  },
  (t) => [index('categories_branch_updated_idx').on(t.branchId, t.updatedAt)],
);

export const products = pgTable(
  'products',
  {
    id: uuid('id').primaryKey(),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    categoryId: uuid('category_id')
      .notNull()
      .references(() => categories.id),
    name: text('name').notNull(),
    /** Price TTC in millimes. */
    price: money('price').notNull(),
    /** VAT rate in basis points (1900 = 19 %). */
    vatRateBp: integer('vat_rate_bp').notNull().default(1900),
    station: text('station', { enum: ['bar', 'kitchen', 'none'] }).notNull().default('none'),
    modifierGroups: jsonb('modifier_groups').notNull().default(sql`'[]'::jsonb`),
    available: boolean('available').notNull().default(true),
    sortOrder: integer('sort_order').notNull().default(0),
    /** Must be set to now() on EVERY change — the POS pulls "changed since cursor". */
    updatedAt: updatedAt(),
    /** Soft delete: the row stays so the POS learns about the deletion on its next pull. */
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
  },
  (t) => [index('products_branch_updated_idx').on(t.branchId, t.updatedAt)],
);

// ── Sync ────────────────────────────────────────────────────────

/** Append-only event log. `id` (UUID v7 from the device) is the idempotency key. */
export const events = pgTable(
  'events',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id').notNull(),
    branchId: uuid('branch_id').notNull(),
    deviceId: uuid('device_id').notNull(),
    staffId: uuid('staff_id'),
    type: text('type').notNull(),
    version: integer('version').notNull(),
    entityId: uuid('entity_id').notNull(),
    deviceSeq: bigint('device_seq', { mode: 'number' }).notNull(),
    occurredAt: timestamp('occurred_at', { withTimezone: true }).notNull(),
    receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
    approvedBy: uuid('approved_by'),
    payload: jsonb('payload').notNull(),
  },
  (t) => [
    index('events_branch_received_idx').on(t.branchId, t.receivedAt),
    index('events_device_seq_idx').on(t.deviceId, t.deviceSeq),
    index('events_entity_idx').on(t.entityId),
  ],
);

/** Problems seen during sync (rejected events, missing sequence numbers). Shown in super-admin. */
export const syncErrors = pgTable('sync_errors', {
  id: uuid('id').primaryKey(),
  deviceId: uuid('device_id').notNull(),
  eventId: uuid('event_id'),
  code: text('code').notNull(),
  details: jsonb('details'),
  createdAt: createdAt(),
});

// ── Sales (projections: read tables BUILT FROM the events) ──────
//
// The events table is the source of truth. These tables are derived from it
// during sync so the owner app can read sales quickly. They can always be
// rebuilt by replaying the events.

export const salesOrders = pgTable(
  'sales_orders',
  {
    /** Same id as the order on the POS (event entityId). */
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id').notNull(),
    branchId: uuid('branch_id').notNull(),
    deviceId: uuid('device_id').notNull(),
    /** open | paid | cancelled | refunded */
    status: text('status', { enum: ['open', 'paid', 'cancelled', 'refunded'] }).notNull().default('open'),
    type: text('type').notNull().default('takeaway'),
    openedAt: timestamp('opened_at', { withTimezone: true }).notNull(),
    closedAt: timestamp('closed_at', { withTimezone: true }),
    /** TTC in millimes, set when paid. */
    total: money('total').notNull().default(0),
    itemCount: integer('item_count').notNull().default(0),
    receiptNumber: text('receipt_number'),
    /** cash | card | mixed */
    paymentMethod: text('payment_method'),
    /** Table the ticket is on (null = counter / takeaway). Name is a snapshot. */
    tableId: uuid('table_id'),
    tableName: text('table_name'),
    /** Refunded after payment: when, why, which manager approved. */
    refundedAt: timestamp('refunded_at', { withTimezone: true }),
    refundReason: text('refund_reason'),
    refundApprovedBy: uuid('refund_approved_by'),
  },
  (t) => [
    index('sales_orders_branch_closed_idx').on(t.branchId, t.closedAt),
    index('sales_orders_branch_status_idx').on(t.branchId, t.status),
  ],
);

export const salesOrderLines = pgTable(
  'sales_order_lines',
  {
    id: uuid('id').primaryKey(),
    orderId: uuid('order_id').notNull(),
    productId: text('product_id').notNull(),
    /** Snapshot at sale time. */
    name: text('name').notNull(),
    unitPrice: money('unit_price').notNull(),
    modifiersPrice: money('modifiers_price').notNull().default(0),
    modifiers: jsonb('modifiers').notNull().default(sql`'[]'::jsonb`),
    qty: integer('qty').notNull(),
    vatRateBp: integer('vat_rate_bp').notNull(),
    voided: boolean('voided').notNull().default(false),
    /** Discount on this line: free | percent | amount (null = none). See shared/money discountOf. */
    discountType: text('discount_type'),
    /** Basis points for percent, millimes for amount. */
    discountValue: integer('discount_value').notNull().default(0),
    /** geste | staff | error | complaint | other */
    discountReason: text('discount_reason'),
    /** Manager who approved it (staff id). */
    discountApprovedBy: uuid('discount_approved_by'),
    /** Removed after being sent to the bar/kitchen: why, and which manager approved. */
    voidReason: text('void_reason'),
    voidApprovedBy: uuid('void_approved_by'),
  },
  (t) => [index('sales_order_lines_order_idx').on(t.orderId)],
);

export const salesPayments = pgTable(
  'sales_payments',
  {
    id: uuid('id').primaryKey(),
    orderId: uuid('order_id').notNull(),
    method: text('method').notNull(),
    amount: money('amount').notNull(),
    tendered: money('tendered').notNull().default(0),
    changeGiven: money('change_given').notNull().default(0),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull(),
  },
  (t) => [index('sales_payments_order_idx').on(t.orderId)],
);

// ── Staff (log in on the POS with a PIN) ────────────────────────

export const staffRoles = ['manager', 'cashier', 'server', 'kitchen'] as const;
export type StaffRole = (typeof staffRoles)[number];

/**
 * People who use the POS. The PIN is checked OFFLINE on the POS, so the POS
 * receives the hash (PBKDF2-SHA256, salted) — never the PIN itself.
 */
export const staff = pgTable(
  'staff',
  {
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id')
      .notNull()
      .references(() => tenants.id),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    name: text('name').notNull(),
    role: text('role', { enum: staffRoles }).notNull(),
    /** "pbkdf2-sha256$<iterations>$<salt b64url>$<hash b64url>" */
    pinHash: text('pin_hash').notNull(),
    active: boolean('active').notNull().default(true),
    /** Set to now() on every change — the POS pulls "changed since cursor". */
    updatedAt: updatedAt(),
    createdAt: createdAt(),
  },
  (t) => [index('staff_branch_updated_idx').on(t.branchId, t.updatedAt)],
);

// ── Floor: rooms and tables (synced to the POS like the menu) ───────

/** "Salle", "Terrasse"… */
export const floorAreas = pgTable(
  'floor_areas',
  {
    id: uuid('id').primaryKey(),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    name: text('name').notNull(),
    sortOrder: integer('sort_order').notNull().default(0),
    updatedAt: updatedAt(),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
  },
  (t) => [index('floor_areas_branch_updated_idx').on(t.branchId, t.updatedAt)],
);

/** A table customers sit at. Name is unique in the branch ("4", "T2"…). */
export const diningTables = pgTable(
  'dining_tables',
  {
    id: uuid('id').primaryKey(),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    areaId: uuid('area_id')
      .notNull()
      .references(() => floorAreas.id),
    name: text('name').notNull(),
    seats: integer('seats').notNull().default(4),
    sortOrder: integer('sort_order').notNull().default(0),
    updatedAt: updatedAt(),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
  },
  (t) => [index('dining_tables_branch_updated_idx').on(t.branchId, t.updatedAt)],
);

// ── Cash sessions (opening float → movements → closing count), from POS events ──

/** One cash drawer's day: opened with a float, closed with a count. Per drawer (POS that takes payments). */
export const cashSessions = pgTable(
  'cash_sessions',
  {
    /** Same id as on the POS (event entityId). */
    id: uuid('id').primaryKey(),
    tenantId: uuid('tenant_id').notNull(),
    branchId: uuid('branch_id').notNull(),
    /** POS that recorded the events (the main POS for every drawer of the café). */
    deviceId: uuid('device_id').notNull(),
    /** The POS whose cash drawer this is. */
    drawerDeviceId: uuid('drawer_device_id').notNull(),
    /** open | closed */
    status: text('status', { enum: ['open', 'closed'] }).notNull().default('open'),
    openedAt: timestamp('opened_at', { withTimezone: true }).notNull(),
    openedBy: uuid('opened_by'),
    openingFloat: money('opening_float').notNull().default(0),
    closedAt: timestamp('closed_at', { withTimezone: true }),
    closedBy: uuid('closed_by'),
    /** All amounts in millimes, as computed by the POS at closing. */
    countedCash: money('counted_cash'),
    expectedCash: money('expected_cash'),
    /** counted − expected: negative = cash missing. */
    difference: money('difference'),
    cashSales: money('cash_sales').notNull().default(0),
    cardSales: money('card_sales').notNull().default(0),
    cashIn: money('cash_in').notNull().default(0),
    cashOut: money('cash_out').notNull().default(0),
    ticketCount: integer('ticket_count').notNull().default(0),
    note: text('note'),
  },
  (t) => [index('cash_sessions_branch_opened_idx').on(t.branchId, t.openedAt)],
);

/** Cash put in or taken out of a drawer during a session ("paid the bread supplier"). */
export const cashMovements = pgTable(
  'cash_movements',
  {
    id: uuid('id').primaryKey(),
    sessionId: uuid('session_id').notNull(),
    /** in | out */
    type: text('type', { enum: ['in', 'out'] }).notNull(),
    amount: money('amount').notNull(),
    reason: text('reason').notNull(),
    staffId: uuid('staff_id'),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull(),
  },
  (t) => [index('cash_movements_session_idx').on(t.sessionId)],
);

// ── Customers (loyalty app) ─────────────────────────────────────

/** People who use the Kahwti customer app. Separate from owners. */
export const customers = pgTable('customers', {
  id: uuid('id').primaryKey(),
  /** Always stored lowercase. */
  email: text('email').notNull().unique(),
  passwordHash: text('password_hash').notNull(),
  name: text('name').notNull(),
  createdAt: createdAt(),
});

export const customerRefreshTokens = pgTable('customer_refresh_tokens', {
  id: uuid('id').primaryKey(),
  customerId: uuid('customer_id')
    .notNull()
    .references(() => customers.id),
  tokenHash: text('token_hash').notNull().unique(),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  revokedAt: timestamp('revoked_at', { withTimezone: true }),
  createdAt: createdAt(),
});

/** A café's loyalty program, set by the owner. */
export const loyaltyPrograms = pgTable('loyalty_programs', {
  branchId: uuid('branch_id')
    .primaryKey()
    .references(() => branches.id),
  enabled: boolean('enabled').notNull().default(false),
  /** Points earned per dinar spent (1 = 1 point per DT). */
  pointsPerDinar: integer('points_per_dinar').notNull().default(1),
  /** [{ id, name, points, kind: free_product | amount_off, productId?, amount? }] */
  rewards: jsonb('rewards').notNull().default(sql`'[]'::jsonb`),
  updatedAt: updatedAt(),
});

/** Every point earned or spent: the balance is the sum, per café. */
export const loyaltyLedger = pgTable(
  'loyalty_ledger',
  {
    id: uuid('id').primaryKey(),
    customerId: uuid('customer_id')
      .notNull()
      .references(() => customers.id),
    branchId: uuid('branch_id').notNull(),
    /** + earned, − spent or taken back. */
    points: integer('points').notNull(),
    /** earn | redeem | refund */
    kind: text('kind', { enum: ['earn', 'redeem', 'refund'] }).notNull(),
    /** The receipt the points come from (earn / refund). One claim per receipt. */
    orderId: uuid('order_id'),
    receiptNumber: text('receipt_number'),
    /** Spent on a reward (redeem). */
    rewardName: text('reward_name'),
    createdAt: createdAt(),
  },
  (t) => [
    index('loyalty_ledger_customer_idx').on(t.customerId, t.branchId),
    // One earn per receipt, and its refund (points taken back) only once.
    uniqueIndex('loyalty_ledger_order_once_idx').on(t.orderId, t.kind).where(sql`${t.kind} <> 'redeem'`),
  ],
);

/**
 * A reward the customer wants, as a short code shown on their phone (valid a few minutes).
 * The POS checks it, then redeems it: the points are spent once (ledger "redeem").
 */
export const loyaltyRedemptions = pgTable(
  'loyalty_redemptions',
  {
    id: uuid('id').primaryKey(),
    /** 6 digits, unique among the branch's active codes. */
    code: text('code').notNull(),
    customerId: uuid('customer_id')
      .notNull()
      .references(() => customers.id),
    branchId: uuid('branch_id').notNull(),
    rewardId: text('reward_id').notNull(),
    rewardName: text('reward_name').notNull(),
    points: integer('points').notNull(),
    kind: text('kind', { enum: ['free_product', 'amount_off'] }).notNull(),
    productId: text('product_id'),
    amount: integer('amount'),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
    /** Replaced by a newer code, or cancelled. */
    cancelledAt: timestamp('cancelled_at', { withTimezone: true }),
    orderId: uuid('order_id'),
    deviceId: uuid('device_id'),
    /** Set when the code is for a gift from the café (no points spent). */
    giftId: uuid('gift_id'),
    createdAt: createdAt(),
  },
  (t) => [index('loyalty_redemptions_code_idx').on(t.branchId, t.code)],
);

// ── Stock (ingredients) ─────────────────────────────────────────

/** Something the café buys and uses: coffee beans (g), milk (ml), croissants (pieces). */
export const stockItems = pgTable(
  'stock_items',
  {
    id: uuid('id').primaryKey(),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    name: text('name').notNull(),
    /** Quantities are whole numbers of this unit. */
    unit: text('unit', { enum: ['g', 'ml', 'piece'] }).notNull(),
    /** Can go below 0 when sales are recorded before a delivery is entered. */
    quantity: integer('quantity').notNull().default(0),
    /** "Stock bas" at or under this quantity; null = no alert. */
    lowThreshold: integer('low_threshold'),
    archived: boolean('archived').notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('stock_items_branch_idx').on(t.branchId)],
);

/** What one unit of a product uses: Cappuccino = 8 g coffee + 150 ml milk. */
export const recipeLines = pgTable(
  'recipe_lines',
  {
    productId: uuid('product_id')
      .notNull()
      .references(() => products.id),
    stockItemId: uuid('stock_item_id')
      .notNull()
      .references(() => stockItems.id),
    qty: integer('qty').notNull(),
  },
  (t) => [primaryKey({ columns: [t.productId, t.stockItemId] })],
);

/** Every change of a stock quantity: sales (automatic), deliveries, losses, counts. */
export const stockMovements = pgTable(
  'stock_movements',
  {
    id: uuid('id').primaryKey(),
    stockItemId: uuid('stock_item_id')
      .notNull()
      .references(() => stockItems.id),
    branchId: uuid('branch_id').notNull(),
    kind: text('kind', { enum: ['sale', 'delivery', 'waste', 'count'] }).notNull(),
    /** + in, − out. */
    delta: integer('delta').notNull(),
    quantityAfter: integer('quantity_after').notNull(),
    /** The paid ticket (sale). */
    orderId: uuid('order_id'),
    note: text('note'),
    /** Owner/manager who entered it (null for sales). */
    userId: uuid('user_id'),
    createdAt: createdAt(),
  },
  (t) => [
    index('stock_movements_item_idx').on(t.stockItemId, t.createdAt),
    // A ticket takes each ingredient out once, even if its events are sent again.
    uniqueIndex('stock_movements_sale_once_idx').on(t.orderId, t.stockItemId).where(sql`${t.kind} = 'sale'`),
  ],
);

// ── Café club (customer consent) and gifts ──────────────────────

/**
 * A customer's choice for one café: joining its club shares their first name and visits
 * with the owner and lets the café send them gifts. Off by default; they can leave any time.
 */
export const customerCafes = pgTable(
  'customer_cafes',
  {
    customerId: uuid('customer_id')
      .notNull()
      .references(() => customers.id),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    optIn: boolean('opt_in').notNull().default(false),
    optInAt: timestamp('opt_in_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.customerId, t.branchId] })],
);

/** A gift the owner sends to club members (a free product or an amount off), used once at the POS. */
export const loyaltyGifts = pgTable(
  'loyalty_gifts',
  {
    id: uuid('id').primaryKey(),
    /** Gifts sent together share it (one "campaign"). */
    campaignId: uuid('campaign_id').notNull(),
    branchId: uuid('branch_id')
      .notNull()
      .references(() => branches.id),
    customerId: uuid('customer_id')
      .notNull()
      .references(() => customers.id),
    name: text('name').notNull(),
    kind: text('kind', { enum: ['free_product', 'amount_off'] }).notNull(),
    productId: text('product_id'),
    amount: integer('amount'),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
    orderId: uuid('order_id'),
    createdBy: uuid('created_by'),
    createdAt: createdAt(),
  },
  (t) => [index('loyalty_gifts_customer_idx').on(t.customerId), index('loyalty_gifts_campaign_idx').on(t.branchId, t.campaignId)],
);

// ── Emails ──────────────────────────────────────────────────────

/** "Mot de passe oublié": a one-time link sent by email (owners and customers). */
export const passwordResets = pgTable('password_resets', {
  id: uuid('id').primaryKey(),
  /** owner = owner_users, customer = customers. */
  kind: text('kind', { enum: ['owner', 'customer'] }).notNull(),
  userId: uuid('user_id').notNull(),
  /** Only the hash of the link's token is kept. */
  tokenHash: text('token_hash').notNull().unique(),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  usedAt: timestamp('used_at', { withTimezone: true }),
  createdAt: createdAt(),
});
